# Let's test with some trigger-like patches on clean images to see if there's a backdoor
# We'll test patches in 4 corners, different sizes (3x3, 4x4, 5x5), and different patterns

# Take a few clean images
test_imgs = x_clean[:10].clone()  # 10 images, 3x32x32

def add_patch(img, corner='tl', size=3, pattern='white'):
    """Add a patch to an image. corner: tl, tr, bl, br"""
    img = img.clone()
    c, h, w = img.shape
    if corner == 'tl':
        r, c_start = 1, 1
    elif corner == 'tr':
        r, c_start = 1, w - size - 1
    elif corner == 'bl':
        r, c_start = h - size - 1, 1
    elif corner == 'br':
        r, c_start = h - size - 1, w - size - 1

    if pattern == 'white':
        patch = torch.ones(3, size, size, dtype=torch.uint8) * 255
    elif pattern == 'checkerboard':
        patch = torch.zeros(3, size, size, dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'random':
        patch = torch.randint(0, 256, (3, size, size), dtype=torch.uint8)

    img[:, r:r+size, c_start:c_start+size] = patch
    return img

# Test various patches on the first clean image
results = []
for corner in ['tl', 'tr', 'bl', 'br']:
    for size in [3, 4, 5]:
        for pattern in ['white', 'checkerboard', 'random']:
            patched = add_patch(test_imgs[0], corner, size, pattern)
            logits = forward(W, patched.unsqueeze(0))
            pred = logits.argmax(dim=1).item()
            results.append((corner, size, pattern, pred, CLASSES[pred]))

